        loop_base regs' N D OW -> getr regs' 19 = S3 -> getr regs' 21 = r -> getr regs' 1 = Z_to_bv 64 0xbec58 ->
        getr regs' 10 = D -> getr regs' 11 = N ->
        keep4 regs regs' -> frame_mod mem mem' regT5_w -> stk_ok RSEGS mem' sp 128 ->
        rdn RSEGS mem' (Z_to_bv 64 0x6ef7d4) 1 = Some (word_to_le_bytes 1 (Z_to_bv 64 1)) ->
        (forall a : word, a <> Z_to_bv 64 0x6ef7d4 -> mem' a = mem a) ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbec44) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes asegs (mkCfg msF mo) K.
