  Lemma seg_T7free : forall s msF mo regs mem (N D OW : word) K,
    loop_base regs N D OW -> getr regs 19 = Z_to_bv 64 0 -> getr regs 21 = Z_to_bv 64 1 ->
    stk_ok RSEGS mem sp 128 -> aro_none mem -> arelro_none mem ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0x90af8) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        loop_base regs' N D OW -> getr regs' 19 = Z_to_bv 64 (-1) -> getr regs' 1 = Z_to_bv 64 0xbec84 -> getr regs' 10 = OW ->
        keep4 regs regs' ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbec68) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes asegs (mkCfg msF mo) K.
