  Lemma seg_T8 : forall s msF mo regs mem (s0 s1 s2 s3 s4 s5 s6 s7 : word) K,
    getr regs 2 = Z_to_bv 64 (bv_unsigned sp - 80) -> getr regs 4 = Z_to_bv 64 0x6f1318 -> getr regs 20 = Z_to_bv 64 0x6ef7d0 ->
    getr regs 22 = Z_to_bv 64 0 -> getr regs 23 = Z_to_bv 64 (-2) ->
    stk_ok RSEGS mem sp 128 -> aro_none mem -> arelro_none mem -> tframe mem s0 s1 s2 s3 s4 s5 s6 s7 ->
    (forall regs' msF' mo',
        as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xbea30) mem rom -> as_AKREL H s (mkCfg msF' mo') -> same_but_materialized mo mo' ->
        getr regs' 2 = sp -> getr regs' 4 = Z_to_bv 64 0x6f1318 -> getr regs' 10 = Z_to_bv 64 0 ->
        getr regs' 8 = s0 -> getr regs' 9 = s1 -> getr regs' 18 = s2 -> getr regs' 19 = s3 -> getr regs' 20 = s4 -> getr regs' 21 = s5 ->
        getr regs' 22 = s6 -> getr regs' 23 = s7 ->
        (forall r : reg, In r [3; 24; 25; 26; 27]%list -> getr regs' r = getr regs r) ->
        realizes asegs (mkCfg msF' mo') K) ->
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xbec84) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    realizes asegs (mkCfg msF mo) K.
